-- =====================================================================
-- Mika Creator — migration 003: LEADS & CONVERSIONS
-- Extends migration 002 (analytics_events + admin). Idempotent: safe to re-run.
--
-- WHAT THIS DOES:
--   1. Expands analytics_events event_type list for the conversion funnel
--      (session_start, hero_slide_view, gallery_open, collection_open,
--       whatsapp_click, telegram_click, pricing_view, custom_request_click,
--       generate_lead) — every existing event type is preserved.
--   2. Replaces insert_event (same signature, no frontend change needed) so
--      conversion clicks AUTO-CREATE a "potential lead" in public.leads
--      (deduped per visitor + channel + collection within 24h).
--      A WhatsApp / Telegram click is ONLY ever a potential lead — the owner
--      manually promotes a lead to PAID / CUSTOMER in the dashboard.
--   3. Creates public.leads
--         status: new / contacted / interested / paid / completed / lost
--   4. Creates public.customers (manual revenue entries; admin-only)
--         status: paid / completed / refunded  (refunded rows never count as revenue)
--   5. Adds admin RPCs:
--        admin_get_conversions      funnel (today / 7d / 28d) + source report +
--                                   page/collection conversion report + lists
--        admin_create_lead / admin_update_lead_status / admin_list_leads / admin_delete_lead
--        admin_add_customer / admin_list_customers / admin_delete_customer
--
-- HOW TO RUN: Supabase Dashboard -> SQL Editor -> paste this entire file -> Run.
-- Requires migration 002 already applied (analytics_events must exist).
-- =====================================================================

begin;

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------
-- 1. EXPAND analytics_events event_type list
--    Drops ANY check constraint on the table that mentions event_type, so it
--    works regardless of the auto-generated constraint name from migration 002.
-- ---------------------------------------------------------------------
do $$
declare r record;
begin
  for r in
    select con.conname
    from pg_constraint con
    join pg_class cls on cls.oid = con.conrelid
    join pg_namespace ns on ns.oid = cls.relnamespace
    where cls.relname = 'analytics_events'
      and con.contype = 'c'
      and pg_get_constraintdef(con.oid) ilike '%event_type%'
  loop
    execute format('alter table public.analytics_events drop constraint %I', r.conname);
  end loop;
end;
$$;

alter table public.analytics_events add constraint analytics_events_event_type_check
  check (event_type in (
    'page_view','session_start','hero_slide_view',
    'gallery_open','collection_open',
    'cta_click','whatsapp_click','telegram_click','contact_click',
    'pricing_view','custom_request_click','generate_lead',
    'outbound_click','like','review_submit','gallery_interaction',
    'redvelvet_click','esa_click'
  ));

-- ---------------------------------------------------------------------
-- 2. SOURCE DERIVATION HELPER
--    Turns a UTM source (or referrer fallback) into a stable bucket that the
--    dashboard reports on. Never invents data: no utm + no referrer = Direct.
-- ---------------------------------------------------------------------
create or replace function public.lead_source(p_referrer text, p_extra jsonb default '{}')
returns text
language sql
immutable
set search_path = public
as $$
  select case
    when lower(coalesce(p_extra ->> 'utm_source', '')) in ('tiktok','facebook','instagram','reddit','google','telegram','twitter','snapchat','youtube','whatsapp')
      then (select case lower(coalesce(p_extra ->> 'utm_source', ''))
                when 'tiktok' then 'TikTok'
                when 'facebook' then 'Facebook'
                when 'instagram' then 'Instagram'
                when 'reddit' then 'Reddit'
                when 'google' then 'Google'
                when 'telegram' then 'Telegram'
                when 'twitter' then 'Twitter'
                when 'snapchat' then 'Snapchat'
                when 'youtube' then 'YouTube'
                when 'whatsapp' then 'WhatsApp'
              end)
    when lower(coalesce(p_extra ->> 'utm_source', '')) <> '' then 'Other'
    when p_referrer is null or p_referrer = '' then 'Direct'
    when p_referrer ilike '%tiktok%' then 'TikTok'
    when p_referrer ilike '%facebook%' or p_referrer ilike '%fb.com%' then 'Facebook'
    when p_referrer ilike '%instagram%' then 'Instagram'
    when p_referrer ilike '%reddit%' then 'Reddit'
    when p_referrer ilike '%google%' then 'Google'
    when p_referrer ilike '%telegram%' or p_referrer ilike '%t.me%' then 'Telegram'
    when p_referrer ilike '%twitter%' or p_referrer ilike '%x.com%' then 'Twitter'
    else 'Other'
  end;
$$;

-- ---------------------------------------------------------------------
-- 3. LEADS TABLE  (private — no anon/authenticated access)
-- ---------------------------------------------------------------------
create table if not exists public.leads (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  ua_hash     text not null default '',
  source      text not null default 'Direct',
  campaign    text not null default '',
  collection  text not null default '',
  page_path   text not null default '',
  channel     text not null default 'whatsapp'
    check (channel in ('whatsapp','telegram','email','custom','manual')),
  status      text not null default 'new'
    check (status in ('new','contacted','interested','paid','completed','lost')),
  note        text not null default ''
);

create index if not exists leads_status_idx on public.leads (status, created_at);
create index if not exists leads_source_idx on public.leads (source, created_at);
create index if not exists leads_created_idx on public.leads (created_at);

alter table public.leads enable row level security;
revoke all on public.leads from anon, authenticated;

-- ---------------------------------------------------------------------
-- 4. CUSTOMERS TABLE  (manual revenue entries; private — admin only)
-- ---------------------------------------------------------------------
create table if not exists public.customers (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  entry_date  date not null default current_date,
  source      text not null default '',
  campaign    text not null default '',
  collection  text not null default '',
  product     text not null default '',
  amount      numeric(12,2) not null default 0,
  status      text not null default 'paid'
    check (status in ('paid','completed','refunded')),
  note        text not null default ''
);

create index if not exists customers_date_idx on public.customers (entry_date, created_at);
create index if not exists customers_status_idx on public.customers (status, created_at);

alter table public.customers enable row level security;
revoke all on public.customers from anon, authenticated;

-- ---------------------------------------------------------------------
-- 5. INSERT EVENT  (replaces migration-002 version; same signature)
--    Auto-creates a potential lead when event_type is a conversion click.
-- ---------------------------------------------------------------------
create or replace function public.insert_event(
  p_event_type text,
  p_path       text default '/',
  p_referrer   text default '',
  p_device     text default 'unknown',
  p_ua_hash    text default '',
  p_extra      jsonb default '{}'
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_recent int;
        v_channel text;
        v_collection text;
begin
  if p_event_type not in (
    'page_view','session_start','hero_slide_view',
    'gallery_open','collection_open',
    'cta_click','whatsapp_click','telegram_click','contact_click',
    'pricing_view','custom_request_click','generate_lead',
    'outbound_click','like','review_submit','gallery_interaction',
    'redvelvet_click','esa_click'
  ) then
    raise exception 'bad event_type';
  end if;

  -- rate limit: max 30 events per minute per UA hash
  if p_ua_hash is not null and p_ua_hash <> '' then
    select count(*) into v_recent
    from public.analytics_events
    where ua_hash = p_ua_hash and created_at > now() - interval '1 minute';
    if v_recent >= 30 then
      raise exception 'rate limited';
    end if;
  end if;

  insert into public.analytics_events (event_type, path, referrer, device, ua_hash, extra)
  values (p_event_type, left(p_path, 500), left(p_referrer, 500), left(p_device, 20), left(p_ua_hash, 64), coalesce(p_extra, '{}'));

  -- Potential lead (NEW). A click is never a customer by itself — the owner
  -- promotes a lead to PAID / adds a customer row manually. Deduped per
  -- visitor + channel + collection within 24h so the lead board stays clean.
  if p_ua_hash is not null and p_ua_hash <> ''
     and p_event_type in ('whatsapp_click', 'telegram_click', 'generate_lead') then
    v_channel := case p_event_type
      when 'whatsapp_click' then 'whatsapp'
      when 'telegram_click' then 'telegram'
      else 'custom' end;
    v_collection := coalesce(nullif(p_extra ->> 'collection', ''), '');

    if not exists (
      select 1 from public.leads l
      where l.ua_hash = p_ua_hash
        and l.channel = v_channel
        and coalesce(l.collection, '') = v_collection
        and l.status = 'new'
        and l.created_at > now() - interval '24 hours'
    ) then
      insert into public.leads (ua_hash, source, campaign, collection, page_path, channel, status)
      values (
        left(p_ua_hash, 64),
        public.lead_source(p_referrer, p_extra),
        left(coalesce(nullif(p_extra ->> 'utm_campaign', ''), ''), 120),
        left(v_collection, 120),
        left(p_path, 500),
        v_channel,
        'new'
      );
    end if;
  end if;

  return json_build_object('ok', true);
end;
$$;

grant execute on function public.insert_event(text, text, text, text, text, jsonb) to anon, authenticated;

-- ---------------------------------------------------------------------
-- 6. ADMIN — LEAD MANAGEMENT
-- ---------------------------------------------------------------------
create or replace function public.admin_create_lead(
  p_source     text default 'Direct',
  p_campaign   text default '',
  p_collection text default '',
  p_page_path  text default '',
  p_channel    text default 'manual',
  p_note       text default ''
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_id bigint;
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;
  if p_channel not in ('whatsapp','telegram','email','custom','manual') then raise exception 'bad channel'; end if;

  insert into public.leads (ua_hash, source, campaign, collection, page_path, channel, note, status)
  values ('',
    left(coalesce(nullif(btrim(p_source), ''), 'Direct'), 40),
    left(coalesce(nullif(btrim(p_campaign), ''), ''), 120),
    left(coalesce(nullif(btrim(p_collection), ''), ''), 120),
    left(coalesce(nullif(btrim(p_page_path), ''), ''), 500),
    p_channel,
    left(coalesce(nullif(btrim(p_note), ''), ''), 500),
    'new')
  returning id into v_id;

  return json_build_object('id', v_id, 'ok', true);
end;
$$;

create or replace function public.admin_update_lead_status(
  p_lead_id bigint,
  p_status  text
)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;
  if p_status not in ('new','contacted','interested','paid','completed','lost') then raise exception 'bad status'; end if;

  update public.leads set status = p_status, updated_at = now() where id = p_lead_id;
  if not found then raise exception 'not found'; end if;
  return json_build_object('ok', true);
end;
$$;

create or replace function public.admin_delete_lead(p_lead_id bigint)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;
  delete from public.leads where id = p_lead_id;
  return json_build_object('ok', true);
end;
$$;

create or replace function public.admin_list_leads(
  p_status text default 'all',
  p_limit  int default 50
)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;

  return (select coalesce(json_agg(l order by l.created_at desc), '[]'::json)
  from (
    select id, created_at, updated_at, source, campaign, collection, page_path, channel, status, note
    from public.leads
    where (p_status = 'all' or status = p_status)
    order by created_at desc
    limit greatest(1, least(p_limit, 300))
  ) l);
end;
$$;

-- ---------------------------------------------------------------------
-- 7. ADMIN — CUSTOMERS / REVENUE
-- ---------------------------------------------------------------------
create or replace function public.admin_add_customer(
  p_entry_date date default current_date,
  p_source     text default '',
  p_campaign   text default '',
  p_collection text default '',
  p_product    text default '',
  p_amount     numeric default 0,
  p_status     text default 'paid',
  p_note       text default ''
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_id bigint;
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;
  if p_status not in ('paid','completed','refunded') then raise exception 'bad status'; end if;
  if coalesce(p_amount, 0) < 0 then raise exception 'bad amount'; end if;

  insert into public.customers (entry_date, source, campaign, collection, product, amount, status, note)
  values (
    coalesce(p_entry_date, current_date),
    left(coalesce(nullif(btrim(p_source), ''), ''), 40),
    left(coalesce(nullif(btrim(p_campaign), ''), ''), 120),
    left(coalesce(nullif(btrim(p_collection), ''), ''), 120),
    left(coalesce(nullif(btrim(p_product), ''), ''), 120),
    coalesce(p_amount, 0),
    p_status,
    left(coalesce(nullif(btrim(p_note), ''), ''), 500))
  returning id into v_id;

  return json_build_object('id', v_id, 'ok', true);
end;
$$;

create or replace function public.admin_list_customers(p_limit int default 100)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;

  return (select coalesce(json_agg(c order by c.entry_date desc, c.created_at desc), '[]'::json)
  from (
    select id, created_at, entry_date, source, campaign, collection, product, amount, status, note
    from public.customers
    order by entry_date desc, created_at desc
    limit greatest(1, least(p_limit, 500))
  ) c);
end;
$$;

create or replace function public.admin_delete_customer(p_customer_id bigint)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;
  delete from public.customers where id = p_customer_id;
  return json_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------
-- 8. ADMIN — FUNNEL / SOURCE / PAGE CONVERSION REPORT
-- ---------------------------------------------------------------------
create or replace function public._funnel_block(p_from timestamptz)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;

  return json_build_object(
    'visitors',        (select count(distinct ua_hash) from public.analytics_events where event_type = 'page_view' and created_at >= p_from),
    'page_views',      (select count(*) from public.analytics_events where event_type = 'page_view' and created_at >= p_from),
    'gallery_opens',   (select count(*) from public.analytics_events where event_type in ('gallery_open','collection_open') and created_at >= p_from),
    'whatsapp_clicks', (select count(*) from public.analytics_events where event_type = 'whatsapp_click' and created_at >= p_from),
    'telegram_clicks', (select count(*) from public.analytics_events where event_type = 'telegram_click' and created_at >= p_from),
    'leads',           (select count(*) from public.leads where created_at >= p_from),
    'customers',       (select count(*) from public.customers where status <> 'refunded' and (created_at >= p_from or entry_date >= p_from::date)),
    'revenue',         (select coalesce(sum(amount), 0) from public.customers where status <> 'refunded' and (created_at >= p_from or entry_date >= p_from::date)),
    'conversion_rate', (
      select case when v.v = 0 then 0 else round(100.0 * l.l / v.v, 1) end
      from (select count(distinct ua_hash) v from public.analytics_events where event_type = 'page_view' and created_at >= p_from) v,
           (select count(*) l from public.leads where created_at >= p_from) l
    )
  );
end;
$$;

create or replace function public.admin_get_conversions()
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_7d  timestamptz := now() - interval '7 days';
        v_28d timestamptz := now() - interval '28 days';
begin
  if not public.is_admin() then raise exception 'unauthorized'; end if;

  return json_build_object(
    'today',  public._funnel_block(date_trunc('day', now())),
    'last7',  public._funnel_block(v_7d),
    'last28', public._funnel_block(v_28d),

    -- Traffic source report (last 28 days). Zero rows are always returned — never invented.
    'sources', (select coalesce(json_agg(r order by r.visitors desc, r.whatsapp_clicks desc), '[]'::json)
      from (
        select s.src as source,
               coalesce(vis.visitors, 0) as visitors,
               coalesce(wa.clicks, 0) as whatsapp_clicks,
               coalesce(ld.leads, 0) as leads,
               round(100.0 * coalesce(ld.leads, 0) / nullif(coalesce(vis.visitors, 0), 0), 1) as conversion_rate
        from (values ('TikTok'),('Facebook'),('Instagram'),('Reddit'),('Google'),('Telegram'),('WhatsApp'),('Twitter'),('Snapchat'),('YouTube'),('Direct'),('Other')) as s(src)
        left join (
          select public.lead_source(referrer, extra) as source, count(distinct ua_hash) as visitors
          from public.analytics_events
          where event_type = 'page_view' and created_at >= v_28d
          group by 1
        ) vis on vis.source = s.src
        left join (
          select public.lead_source(referrer, extra) as source, count(*) as clicks
          from public.analytics_events
          where event_type = 'whatsapp_click' and created_at >= v_28d
          group by 1
        ) wa on wa.source = s.src
        left join (
          select source, count(*) as leads from public.leads where created_at >= v_28d group by 1
        ) ld on ld.source = s.src
      ) r),

    -- Page / collection conversion report (last 28 days).
    'pages', (select coalesce(json_agg(r order by r.visitors desc, r.views desc), '[]'::json)
      from (
        with keys as (
          select path, '' as collection from public.analytics_events where event_type = 'page_view' and created_at >= v_28d
          union
          select path, coalesce(extra ->> 'collection', '') from public.analytics_events where event_type in ('gallery_open','collection_open') and created_at >= v_28d
          union
          select path, coalesce(extra ->> 'collection', '') from public.analytics_events where event_type = 'whatsapp_click' and created_at >= v_28d
        ),
        pv as (select path, count(*) views, count(distinct ua_hash) visitors from public.analytics_events where event_type = 'page_view' and created_at >= v_28d group by 1),
        op as (select path, coalesce(extra ->> 'collection', '') c, count(*) opens from public.analytics_events where event_type in ('gallery_open','collection_open') and created_at >= v_28d group by 1, 2),
        wa as (select path, coalesce(extra ->> 'collection', '') c, count(*) clicks from public.analytics_events where event_type = 'whatsapp_click' and created_at >= v_28d group by 1, 2),
        ld as (select page_path, count(*) leads from public.leads where created_at >= v_28d group by 1)
        select k.path,
               coalesce(nullif(k.collection, ''), k.path) as label,
               k.collection,
               coalesce(pv.visitors, 0) as visitors,
               coalesce(pv.views, 0) as views,
               coalesce(op.opens, 0) as gallery_opens,
               coalesce(wa.clicks, 0) as whatsapp_clicks,
               coalesce(ld.leads, 0) as leads
        from keys k
        left join pv on pv.path = k.path
        left join op on op.path = k.path and op.c = k.collection
        left join wa on wa.path = k.path and wa.c = k.collection
        left join ld on ld.page_path = k.path
      ) r),

    'recent_leads', (select coalesce(json_agg(l order by l.created_at desc), '[]'::json)
      from (select id, created_at, source, campaign, collection, page_path, channel, status, note
            from public.leads order by created_at desc limit 30) l),

    'recent_customers', (select coalesce(json_agg(c order by c.entry_date desc, c.created_at desc), '[]'::json)
      from (select id, created_at, entry_date, source, campaign, collection, product, amount, status, note
            from public.customers order by entry_date desc, created_at desc limit 30) c)
  );
end;
$$;

-- ---------------------------------------------------------------------
-- 9. GRANTS
-- ---------------------------------------------------------------------
grant execute on function public.admin_create_lead(text, text, text, text, text, text) to authenticated;
grant execute on function public.admin_update_lead_status(bigint, text) to authenticated;
grant execute on function public.admin_list_leads(text, int) to authenticated;
grant execute on function public.admin_delete_lead(bigint) to authenticated;
grant execute on function public.admin_add_customer(date, text, text, text, text, numeric, text, text) to authenticated;
grant execute on function public.admin_list_customers(int) to authenticated;
grant execute on function public.admin_delete_customer(bigint) to authenticated;
grant execute on function public.admin_get_conversions() to authenticated;

-- =====================================================================
-- DONE. After running:
--   * anon can still insert analytics events (unchanged)
--   * conversion clicks now auto-create leads with status NEW
--   * sign in at /admin/ with Mika's admin account to see LEADS & CONVERSIONS
-- =====================================================================
commit;


-- ---------------------------------------------------------------------
-- [source: 004_admin_monique.sql]
-- ---------------------------------------------------------------------
-- =====================================================================
-- Mika Creator — migration 004: AUTHORIZE ADMIN (Monique)
-- Extends migration 002's public.admin_users / public.is_admin() so the
-- authorised admin account belongs to Monique (auth email:
-- mikacreator8@gmail.com).
--
-- SECURITY MODEL (server-side, same model as 002):
--   * Passwords NEVER appear in code or this repo. Sign-in uses Supabase
--     Auth: the client posts email+password to /auth/v1/token; the password
--     lives only in Supabase Auth (hashed) and is never stored or logged
--     by this project.
--   * Authorization is 100% server-side: every admin RPC is SECURITY
--     DEFINER and rejects unless public.is_admin() is true, which checks
--     the signed-in JWT email against public.admin_users.
--   * The ONLY privilege-escalation surface is this bootstrap function
--     (authorize_admin). It deliberately does NOT check is_admin() — it IS
--     the bootstrap. It is protected by: (a) EXECUTE granted ONLY to
--     service_role, (b) a hard REVOKE of admin_users from anon/authenticated,
--     and (c) it verifies the target email actually has a Supabase Auth
--     user before authorizing. A public visitor can never run it.
--   * No public signup mechanism for the admin is created.
--   * /admin/ is generated robots=noindex,nofollow and omitted from the
--     sitemap.
--
-- HOW TO AUTHORIZE MONIQUE (after this migration + its dependencies 002/003
-- have been applied):
--   Supabase Dashboard -> SQL Editor -> run:
--     select public.authorize_admin('mikacreator8@gmail.com', 'Monique');
--   (idempotent — safe to re-run. If the Auth user for that email does not
--   exist yet, the function raises a clear error; create it under
--   Authentication > Users first, and confirm the activation email.)
--
-- =====================================================================

begin;

-- ---------------------------------------------------------------------
-- 1. Metadata columns (optional, purely for readability)
-- ---------------------------------------------------------------------
alter table public.admin_users add column if not exists name text not null default 'Monique';
alter table public.admin_users add column if not exists authorized_at timestamptz not null default now();

-- ---------------------------------------------------------------------
-- 2. AUTHORIZE helper (canonical name — matches the supported call)
--    Verifies the Auth user exists, then upserts the admin mapping.
-- ---------------------------------------------------------------------
create or replace function public.authorize_admin(
  p_email text,
  p_name  text default null
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_email text;
begin
  v_email := lower(btrim(coalesce(p_email, '')));
  if v_email = '' or position('@' in v_email) = 0 then
    raise exception 'bad email';
  end if;

  -- Only ever authorize a real auth account — no orphan admin rows.
  if not exists (select 1 from auth.users where lower(email) = v_email) then
    raise exception 'No Supabase Auth user exists for % yet. Create it under Authentication > Users first.', v_email;
  end if;

  insert into public.admin_users (email, name, authorized_at)
  values (v_email, coalesce(nullif(btrim(p_name), ''), 'Monique'), now())
  on conflict (email) do update
    set name = excluded.name,
        authorized_at = now()
  returning email into v_email;

  return json_build_object('email', v_email, 'ok', true);
end;
$$;

-- Alias for compatibility with the earlier draft name (004 v1).
create or replace function public.admin_authorize_admin(p_email text, p_name text default null)
returns json
language sql
security definer
set search_path = public
as $$
  select public.authorize_admin(p_email, p_name);
$$;

-- ---------------------------------------------------------------------
-- 3. REVOKE helper + alias  (remove an admin by email)
-- ---------------------------------------------------------------------
create or replace function public.revoke_admin(p_email text)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if lower(btrim(coalesce(p_email, ''))) = '' then
    raise exception 'bad email';
  end if;
  delete from public.admin_users where email = lower(btrim(p_email));
  return json_build_object('ok', true);
end;
$$;

create or replace function public.admin_revoke_admin(p_email text)
returns json
language sql
security definer
set search_path = public
as $$
  select public.revoke_admin(p_email);
$$;

-- ---------------------------------------------------------------------
-- 4. Privilege lockdown (defence in depth on top of RLS)
-- ---------------------------------------------------------------------
revoke all on public.admin_users from anon;
revoke all on public.admin_users from authenticated;

grant execute on function public.authorize_admin(text, text) to service_role;
grant execute on function public.admin_authorize_admin(text, text) to service_role;
grant execute on function public.revoke_admin(text) to service_role;
grant execute on function public.admin_revoke_admin(text) to service_role;

commit;

-- =====================================================================
-- DONE. Run the authorize one-liner from the header to grant Monique.
-- Emails / passwords are never in the repo. No admin password is created
-- here — it is set once in Authentication > Users.
-- =====================================================================


-- ---------------------------------------------------------------------
-- [source: 005_admin_auth_hardening.sql]
-- ---------------------------------------------------------------------
-- =====================================================================
-- Mika Creator — migration 005: ADMIN AUTH HARDENING (grant + RLS repair)
-- Run AFTER 001, schema.sql, 002, 003 and 004. Idempotent: safe to re-run.
--
-- WHY THIS FILE EXISTS
--   The previous admin setup failed repeatedly. Root cause of the SQL side was
--   a GRANT written against the wrong function identity signature
--   (`admin_get_stats(int)` for a function declared `(p_days int, p_range text)`).
--   Postgres rejects that with "function does not exist", and the Supabase SQL
--   Editor runs a pasted script inside ONE transaction — so that single line
--   rolled back every table, function, policy and grant before it, and the
--   admin dashboard could never authenticate. Hand-written GRANTs are the weak
--   link, so this file stops hand-writing them.
--
-- WHAT THIS DOES
--   1. Ensures every table the application touches exists (CREATE IF NOT EXISTS).
--      Nothing is dropped, truncated or reset — all existing rows are kept.
--   2. GRANT REPAIR, SIGNATURE-PROOF. Resolves each function from the live
--      catalog via pg_proc + `oid::regprocedure`, so the exact declared
--      signature is used automatically. A function that is absent produces a
--      WARNING, never an error, so this file can never abort a run.
--   3. REVOKEs the sensitive surface from anon/authenticated (raw votes, raw
--      reviews, admin_users, leads, customers, custom_requests) and revokes the
--      privilege-escalation helpers from the browser roles.
--   4. RLS audit: RLS enabled everywhere; the public site keeps only the
--      minimum it needs — approved comments, comment submission, analytics
--      event insert, and the aggregate read views.
--   5. Re-declares authorize_admin / revoke_admin (idempotent) and prints a
--      verification report.
--
-- SERVICE-ROLE KEYS
--   This project is fully static. There is no service-role key in the repo and
--   none is needed: the browser only ever holds the publishable anon key, and
--   every admin operation is authorised server-side by is_admin() inside a
--   SECURITY DEFINER function. authorize_admin is granted to service_role only
--   (plus the owner, i.e. you in the SQL Editor) so a visitor can never call it.
--
-- FINAL MANUAL STEP (after this file)
--   Supabase Dashboard -> Authentication -> Users -> Add User
--     email:    mikacreator8@gmail.com
--     password: (choose a strong one — set once, never stored in this repo)
--     tick "Auto Confirm User" so sign-in works without an email round-trip.
--   Then, still in the SQL Editor:
--     select public.authorize_admin('mikacreator8@gmail.com', 'Monique');
--   Then sign in at https://www.mikacreator.co.za/admin/login/
-- =====================================================================

begin;

-- ---------------------------------------------------------------------
-- 1. TABLES — create-if-missing only. No drops, no data loss.
-- ---------------------------------------------------------------------
create extension if not exists pgcrypto;

create table if not exists public.comments (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  object_type text not null default 'collection'
    check (object_type in ('asset','collection','global')),
  object_id   text not null default 'home',
  voter_id    text not null default '',
  name        text not null default 'Guest',
  text        text not null,
  status      text not null default 'pending'
    check (status in ('pending','approved','rejected'))
);

create table if not exists public.analytics_events (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  event_type  text not null,
  path        text not null default '/',
  referrer    text not null default '',
  device      text not null default 'unknown'
    check (device in ('desktop','mobile','tablet','unknown')),
  ua_hash     text not null default '',
  extra       jsonb not null default '{}'
);

create table if not exists public.admin_users (
  id         uuid primary key default gen_random_uuid(),
  email      text not null unique,
  created_at timestamptz not null default now()
);

create table if not exists public.custom_requests (
  id           bigint generated always as identity primary key,
  created_at   timestamptz not null default now(),
  name         text not null default '',
  package_id   text not null default '',
  type         text not null default '',
  custom_word  text not null default '',
  colour       text not null default '',
  placement    text not null default '',
  colour_custom text not null default '',
  location     text not null default '',
  lighting     text not null default '',
  outfit       text not null default '',
  background   text not null default '',
  mood         text not null default '',
  camera       text not null default '',
  video        text not null default '',
  other        text not null default '',
  detailed     text not null default '',
  delivery     text not null default '',
  contact_name text not null default '',
  email        text not null default '',
  method       text not null default '',
  status       text not null default 'new'
    check (status in ('new','reviewing','accepted','declined','done'))
);

create table if not exists public.leads (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  ua_hash     text not null default '',
  source      text not null default 'Direct',
  campaign    text not null default '',
  collection  text not null default '',
  page_path   text not null default '',
  channel     text not null default 'whatsapp'
    check (channel in ('whatsapp','telegram','email','custom','manual')),
  status      text not null default 'new'
    check (status in ('new','contacted','interested','paid','completed','lost')),
  note        text not null default ''
);

create table if not exists public.customers (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  entry_date  date not null default current_date,
  source      text not null default '',
  campaign    text not null default '',
  collection  text not null default '',
  product     text not null default '',
  amount      numeric(12,2) not null default 0,
  status      text not null default 'paid'
    check (status in ('paid','completed','refunded')),
  note        text not null default ''
);

create table if not exists public.assets (
  slug          text primary key,
  collection    text not null,
  visibility    text not null default 'preview'
    check (visibility in ('preview','public','hidden')),
  blur_required boolean not null default true,
  title         text,
  updated_at    timestamptz not null default now()
);

-- Idempotent supporting objects
create index if not exists comments_object_idx
  on public.comments (object_type, object_id, status, created_at);
create index if not exists analytics_events_type_idx
  on public.analytics_events (event_type, created_at);
create index if not exists analytics_events_path_idx
  on public.analytics_events (path, created_at);
create index if not exists analytics_events_date_idx
  on public.analytics_events (created_at);
create index if not exists custom_requests_status_idx
  on public.custom_requests (status, created_at);
create index if not exists leads_status_idx  on public.leads (status, created_at);
create index if not exists leads_source_idx  on public.leads (source, created_at);
create index if not exists leads_created_idx on public.leads (created_at);
create index if not exists customers_date_idx   on public.customers (entry_date, created_at);
create index if not exists customers_status_idx on public.customers (status, created_at);

-- ---------------------------------------------------------------------
-- 2. GRANT REPAIR — resolved from the catalog, so it cannot mismatch.
--    For each (function name, role) pair we look up EVERY declared overload
--    and grant its real identity signature.
-- ---------------------------------------------------------------------
do $$
declare
  spec  text[][];
  item  text[];
  v_fn  text;
  v_role text;
  r     record;
  hits  int;
  total_granted int := 0;
  missing text := '';
begin
  spec := array[
    -- public site (unauthenticated visitors) — minimum required surface
    array['toggle_vote',            'anon'],
    array['toggle_vote',            'authenticated'],
    array['count_likes',            'anon'],
    array['count_likes',            'authenticated'],
    array['count_collection_likes', 'anon'],
    array['count_collection_likes', 'authenticated'],
    array['list_comments',          'anon'],
    array['list_comments',          'authenticated'],
    array['insert_comment',         'anon'],
    array['insert_comment',         'authenticated'],
    array['insert_review',          'anon'],
    array['insert_review',          'authenticated'],
    array['get_review_stats',       'anon'],
    array['get_review_stats',       'authenticated'],
    array['insert_event',           'anon'],
    array['insert_event',           'authenticated'],
    array['submit_custom_request',  'anon'],
    array['submit_custom_request',  'authenticated'],
    -- admin surface — authenticated only; each function re-checks is_admin()
    array['admin_get_today_stats',        'authenticated'],
    array['admin_get_stats',              'authenticated'],
    array['admin_list_comments',          'authenticated'],
    array['admin_moderate_comment',       'authenticated'],
    array['admin_list_custom_requests',   'authenticated'],
    array['admin_get_conversions',        'authenticated'],
    array['admin_list_leads',             'authenticated'],
    array['admin_create_lead',            'authenticated'],
    array['admin_update_lead_status',     'authenticated'],
    array['admin_delete_lead',            'authenticated'],
    array['admin_list_customers',         'authenticated'],
    array['admin_add_customer',           'authenticated'],
    array['admin_delete_customer',        'authenticated'],
    array['is_admin',                     'authenticated']
  ];

  foreach item slice 1 in array spec loop
    v_fn   := item[1];
    v_role := item[2];
    hits   := 0;
    for r in
      select p.oid::regprocedure::text as sig
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and p.proname = v_fn
    loop
      execute format('grant execute on function %s to %I', r.sig, v_role);
      hits := hits + 1;
    end loop;
    if hits = 0 then
      missing := missing || v_fn || ' ';
    else
      total_granted := total_granted + hits;
    end if;
  end loop;

  raise notice 'grant repair: % signature(s) granted', total_granted;
  if missing <> '' then
    raise warning 'not present yet (run the earlier migrations first): %', missing;
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- 3. REVOKE the sensitive surface from the browser roles.
--    These are re-asserted every run, so a previously over-broad grant
--    (e.g. a hand-made "make it work" grant) is undone here.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'votes', 'reviews', 'admin_users', 'leads', 'customers',
    'custom_requests', 'analytics_events'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('revoke all on table public.%I from anon, authenticated', t);
    end if;
  end loop;
end;
$$;

-- Public read surface is the aggregate views only (no voter_id, no status).
do $$
declare v text;
begin
  foreach v in array array['vote_counts','approved_comments','review_stats'] loop
    if to_regclass('public.' || v) is not null then
      execute format('grant select on public.%I to anon, authenticated', v);
    else
      raise warning 'view public.% does not exist yet — run schema.sql first', v;
    end if;
  end loop;
end;
$$;

-- Privilege-escalation helpers: service_role (and the owner) only.
-- A public visitor can never authorize an admin.
do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure::text as sig
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in ('authorize_admin','admin_authorize_admin',
                        'revoke_admin','admin_revoke_admin')
  loop
    execute format('revoke execute on function %s from anon, authenticated', r.sig);
    execute format('revoke execute on function %s from public', r.sig);
    execute format('grant  execute on function %s to service_role', r.sig);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------
-- 4. ROW LEVEL SECURITY AUDIT
--    RLS on for every app table. The public site gets exactly two write
--    paths (comment submit, analytics event) and read-only aggregate views.
--    Nothing is made publicly writable.
--
--    NOTE: `ENABLE` is deliberate and `FORCE` is deliberately NOT used.
--    Every admin and public RPC in this project is SECURITY DEFINER and
--    therefore executes as the table owner. Enabling RLS makes anon and
--    authenticated subject to it, but leaves the owner unconstrained, which
--    is what those functions rely on. Adding FORCE would make the OWNER
--    subject to RLS too, and since a table with no permissive policy denies
--    everything, that would break insert_comment, insert_event, toggle_vote,
--    authorize_admin and the probe-row cleanup. Do not add FORCE here.
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'votes','comments','reviews','assets','analytics_events',
    'admin_users','custom_requests','leads','customers'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('alter table public.%I enable row level security', t);
    end if;
  end loop;
end;
$$;

-- comments: the only supported write path is the SECURITY DEFINER RPC
-- insert_comment(), so anon/authenticated hold no table grant and cannot
-- insert directly. The policies below are the second line of defence: if a
-- table grant is ever added by mistake, they still prevent (a) anyone
-- reading unapproved comments and (b) anyone self-approving their own
-- comment by inserting status = 'approved'.
do $$
begin
  if to_regclass('public.comments') is not null then
    if not exists (select 1 from pg_policies
                   where schemaname='public' and tablename='comments'
                     and policyname='comments_insert_policy') then
      create policy comments_insert_policy on public.comments
        for insert to anon, authenticated with check (status = 'pending');
    end if;
    if not exists (select 1 from pg_policies
                   where schemaname='public' and tablename='comments'
                     and policyname='comments_select_approved') then
      create policy comments_select_approved on public.comments
        for select to anon, authenticated using (status = 'approved');
    end if;
  end if;
end;
$$;

-- analytics_events: append-only from the browser. No SELECT policy, so even
-- if a grant were added the raw event log stays unreadable from a browser.
do $$
begin
  if to_regclass('public.analytics_events') is not null then
    if not exists (select 1 from pg_policies
                   where schemaname='public' and tablename='analytics_events'
                     and policyname='analytics_insert_policy') then
      create policy analytics_insert_policy on public.analytics_events
        for insert to anon, authenticated with check (true);
    end if;
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- 5. ONE-TIME CLEANUP
--    A diagnostic probe against the legacy v1 toggle_vote RPC inserted a
--    synthetic row (voter_id '__probe__'). Migration 001 already discards it
--    (unmapped record_key -> null object_id -> deleted), but this makes the
--    cleanup explicit and independent of run order.
-- ---------------------------------------------------------------------
delete from public.votes where voter_id = '__probe__';

-- ---------------------------------------------------------------------
-- 6. AUTHORIZE THE ADMIN (idempotent re-declare from 004)
--    Verifies a real Supabase Auth user exists before writing the mapping,
--    so there can never be an orphan admin row.
-- ---------------------------------------------------------------------
alter table public.admin_users add column if not exists name text not null default 'Monique';
alter table public.admin_users add column if not exists authorized_at timestamptz not null default now();

create or replace function public.authorize_admin(
  p_email text,
  p_name  text default null
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare v_email text;
begin
  v_email := lower(btrim(coalesce(p_email, '')));
  if v_email = '' or position('@' in v_email) = 0 then
    raise exception 'bad email';
  end if;

  if not exists (select 1 from auth.users where lower(email) = v_email) then
    raise exception 'No Supabase Auth user exists for % yet. Create it under Authentication > Users first.', v_email;
  end if;

  insert into public.admin_users (email, name, authorized_at)
  values (v_email, coalesce(nullif(btrim(p_name), ''), 'Monique'), now())
  on conflict (email) do update
    set name = excluded.name,
        authorized_at = now()
  returning email into v_email;

  return json_build_object('email', v_email, 'ok', true);
end;
$$;

create or replace function public.revoke_admin(p_email text)
returns json
language plpgsql
security definer
set search_path = public
as $$
begin
  if lower(btrim(coalesce(p_email, ''))) = '' then
    raise exception 'bad email';
  end if;
  delete from public.admin_users where email = lower(btrim(p_email));
  return json_build_object('ok', true);
end;
$$;

commit;

-- ---------------------------------------------------------------------
-- 7. VERIFICATION REPORT (read-only, safe to re-run)
-- ---------------------------------------------------------------------
select 'authorized admins' as check, count(*)::text as value
  from public.admin_users
union all
select 'auth users', count(*)::text from auth.users
union all
select 'votes rows',      count(*)::text from public.votes
union all
select 'reviews rows',    count(*)::text from public.reviews
union all
select 'comments rows',   count(*)::text from public.comments
union all
select 'events rows',     count(*)::text from public.analytics_events
union all
select 'leads rows',      count(*)::text from public.leads
union all
select 'customers rows',  count(*)::text from public.customers;

-- Expected after a successful run:
--   authorized admins : 1        (after the authorize_admin one-liner)
--   votes rows        : 2        (the 2 pre-existing likes, unmapped probe gone)
--   reviews rows      : 0
--   others            : 0 until real traffic arrives
